async (page) => {
  const cdp=await page.context().newCDPSession(page);
  await cdp.send('Network.enable');
  await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});
  await page.addInitScript(()=>{
    window.__teacherPerf={lcp:null,cls:0,longTasks:0};
    new PerformanceObserver(list=>{for(const entry of list.getEntries())window.__teacherPerf.lcp=entry.startTime;}).observe({type:'largest-contentful-paint',buffered:true});
    new PerformanceObserver(list=>{for(const entry of list.getEntries())if(!entry.hadRecentInput)window.__teacherPerf.cls+=entry.value;}).observe({type:'layout-shift',buffered:true});
    new PerformanceObserver(list=>{for(const entry of list.getEntries())window.__teacherPerf.longTasks+=Math.max(0,entry.duration-50);}).observe({type:'longtask',buffered:true});
  });
  const all=[];let requests=[];
  page.on('request',request=>{if(request.url().includes('/api/v1/teacher/'))requests.push({method:request.method(),path:new URL(request.url()).pathname});});
  for(const profile of [{name:'mobile320',width:320,height:850,cpu:4,latency:150,download:200000,upload:93750},{name:'desktop1280',width:1280,height:900,cpu:1,latency:20,download:1250000,upload:1250000}]){
    await page.setViewportSize({width:profile.width,height:profile.height});
    await cdp.send('Emulation.setCPUThrottlingRate',{rate:profile.cpu});
    await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:profile.latency,downloadThroughput:profile.download,uploadThroughput:profile.upload});
    for(let round=0;round<3;round++)for(const [variant,port] of [['baseline',5183],['current',5184]]){
      await page.goto('about:blank');await cdp.send('Network.clearBrowserCache');requests=[];
      await page.goto(`http://127.0.0.1:${port}/.tmp/teacher-upgrade-integrated/index.html`,{waitUntil:'domcontentloaded'});
      await page.getByText('Una transacción atómica aplica todos los cambios o ninguno. Si falla la segunda escritura, se revierten ambas.',{exact:true}).waitFor({state:'visible',timeout:60000});
      const ready=await page.evaluate(()=>performance.now());
      await page.waitForLoadState('networkidle');
      await cdp.send('HeapProfiler.collectGarbage');
      const heap=await cdp.send('Runtime.getHeapUsage');
      const data=await page.evaluate(()=>({
        ...window.__teacherPerf,fcp:performance.getEntriesByName('first-contentful-paint')[0]?.startTime??null,
        document_width:document.documentElement.scrollWidth,viewport:innerWidth,
        resources:performance.getEntriesByType('resource').filter(r=>r.name.includes('/assets/')).map(r=>({name:new URL(r.name).pathname,encoded:r.encodedBodySize,decoded:r.decodedBodySize,transfer:r.transferSize})),
      }));
      all.push({variant,profile:profile.name,round:round+1,ready_ms:ready,heap_used_bytes:heap.usedSize,api_requests:requests,...data});
    }
  }
  await cdp.send('Emulation.setCPUThrottlingRate',{rate:1});
  await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:0,downloadThroughput:-1,uploadThroughput:-1});
  return {task:'teacher_reader_comparison',browser:await page.context().browser().version(),profiles:{mobile320:{cpu:4,latency:150,downloadBytesPerSec:200000},desktop1280:{cpu:1,latency:20,downloadBytesPerSec:1250000}},runs:all};
}
